def missing_alphabets(s):
    def find_missing_letters(s):
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        missing = []
        for char in alphabet:
            if s.count(char) < alphabet.count(char):
                missing.extend([char] * (alphabet.count(char) - s.count(char)))
        return ''.join(missing)

    def process_string(s):
        result = ''
        i = 0
        while i < len(s):
            char = s[i]
            count = s.count(char)
            if count > 1:
                result += char * count
                i += count
            else:
                result += char
                i += 1
        return result

    def get_unique_chars(s):
        return ''.join(sorted(set(s)))

    def find_repeated_chars(s):
        repeated = ''
        for char in s:
            if s.count(char) > 1:
                repeated += char * (s.count(char) - 1)
        return repeated

    def find_missing_repeated_chars(s):
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        missing_repeated = []
        for char in alphabet:
            if s.count(char) < alphabet.count(char):
                missing_repeated.extend([char] * (alphabet.count(char) - s.count(char)))
        repeated = find_repeated_chars(''.join(missing_repeated))
        return repeated

    processed_s = process_string(s)
    unique_chars = get_unique_chars(processed_s)
    missing = find_missing_letters(unique_chars)
    missing_repeated = find_missing_repeated_chars(missing)
    return missing_repeated

