def extendedEuclidean(a, b):
    """Extended Euclidean Algorithm to find the greatest common divisor (gcd) and the coefficients of Bézout's identity."""
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extendedEuclidean(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def inverseMod(a, m):
    """Find the modular multiplicative inverse of a modulo m."""
    gcd, x, _ = extendedEuclidean(a, m)
    if gcd != 1:
        return None  # a and m are not coprime, no modular inverse exists
    else:
        return x % m  # Ensure the result is positive

# Entrypoint function to orchestrate the process
def solve(a, m):
    return inverseMod(a, m)
