from datetime import datetime, timedelta

def get_day_of_week(day_num):
    days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    return days[day_num % 7]

def get_time_of_day(minutes):
    midnight = datetime.strptime('00:00', '%H:%M')
    time_delta = timedelta(minutes=minutes)
    current_time = midnight + time_delta
    return current_time.strftime('%H:%M')

def day_and_time(mins):
    day_index = (datetime.now().weekday() + mins // 1440) % 7
    time_str = get_time_of_day(mins % 1440)
    return f"{get_day_of_week(day_index)} {time_str}"

