                if current_block:
                    blocks.append(''.join(current_block))
                    current_block = [char]
        if current_block:
            blocks.append(''.join(current_block))
        return blocks

    def join_blocks(blocks):
        return '-'.join(blocks)

    characters = list(s)
    grouped_chars = sort_and_group(characters)
    blocks = create_blocks(grouped_chars)
    return join_blocks(blocks)
