import math

def find_cat_positions(yard):
    positions = {'L': [], 'M': [], 'R': []}
    for i, row in enumerate(yard):
        for j, char in enumerate(row):
            if char in positions:
                positions[char].append((i, j))
    return positions

def calculate_distance(pos1, pos2):
    return math.sqrt((pos1[0] - pos2[0]) ** 2 + (pos1[1] - pos2[1]) ** 2)

def check_distances(positions, min_distance):
    cats = ['L', 'M', 'R']
    for i in range(len(cats)):
        for j in range(i + 1, len(cats)):
            if calculate_distance(positions[cats[i]][0], positions[cats[j]][0]) < min_distance:
                return False
    return True

def peaceful_yard(yard, min_distance):
    positions = find_cat_positions(yard)
    if len(positions['L']) + len(positions['M']) + len(positions['R']) <= 1:
        return True
    return check_distances(positions, min_distance)
